 43	#define ICU_RETURN_ON_INVALID_DEVS(dev) do {\
 44	                if ((dev) >= INT_SRC_NONE) {\
 45	                    return BK_ERR_INT_DEVICE_NONE;\
 46	                }\
 47	            } while(0)
